-- Investors and grants founders can find (Fundraising → Find investors & grants): a curated list of fintech,
-- telco, fraud / identity, crypto, CPaaS and Africa-focused investors, development lenders and grant programmes.
-- General information only (who they are, what they back, stages, links); nothing about any one company's plans.
ALTER TABLE crm.prospects DROP CONSTRAINT IF EXISTS prospects_type_check;
ALTER TABLE crm.prospects ADD CONSTRAINT prospects_type_check CHECK (type IN ('vc', 'angel_network', 'accelerator', 'corporate', 'government', 'foundation', 'competition', 'credits', 'dfi', 'lender', 'other'));
ON CONFLICT (lower(name), kind) DO NOTHING;
